                                          ? f.name.charAt(0).toUpperCase()
                                          : "A"}
                                      </div>
                                    )}

                                    <div>
                                      <div
                                        className={`font-bold ${
                                          isDarkMode
                                            ? "text-white"
                                            : "text-purple-900"
                                        }`}
                                      >
                                        {f.name || "Anonymous"}
                                      </div>
                                      <span
                                        className={`text-xs ${
                                          isDarkMode
                                            ? "text-gray-400"
                                            : "text-gray-500"
                                        }`}
                                      >
                                        {new Date(
                                          f.created_at
                                        ).toLocaleString()}
                                      </span>
                                    </div>
                                  </div>
                                </div>

